from typing import List, Any
import random

class TestStrategy:
    """Base class for test generation strategies."""
    def generate(self, metadata: Any) -> List[str]:
        raise NotImplementedError

class BoundaryStrategy(TestStrategy):
    """Generates tests for edge cases: None, empty strings, max/min ints."""
    def generate(self, metadata) -> List[str]:
        edge_cases = {
            "str": ["", " ", "\n", "A" * 1000],
            "int": [0, -1, 1, 2**31-1, -2**31],
            "list": [[], [None], [1] * 100],
            "dict": [{}, {"key": None}]
        }
        
        tests = []
        for arg in metadata.args:
            # Simplified: in production, this would use type hints from metadata.returns
            for type_key, values in edge_cases.items():
                for val in values:
                    tests.append(f"test_{metadata.name}_with_{type_key}_edge_case_{val}")
        return tests

class LogicBranchStrategy(TestStrategy):
    """Generates tests specifically to hit every identified branch."""
    def generate(self, metadata) -> List[str]:
        return [f"test_{metadata.name}_branch_{i}" for i in range(metadata.branches)]